
const $=id=>document.getElementById(id);
const clean=s=>(s??"").toString().replace(/[ \t]+/g," ").replace(/\s*\n\s*/g,"\n").trim();
const norm=s=>clean(s).normalize("NFD").replace(/[\u0300-\u036f]/g,"").toLowerCase();
const esc=s=>(s??"").toString().replace(/[&<>\"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]));
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
let STATE={file:null,buffer:null,hash:"",doc:null,score:null,issues:[],rubric:[],locks:[],sections:{},pageRatio:null};

function qn(node,name){return node.getElementsByTagNameNS("http://schemas.openxmlformats.org/wordprocessingml/2006/main",name)}
function attr(node,name){if(!node)return null;return node.getAttributeNS("http://schemas.openxmlformats.org/wordprocessingml/2006/main",name)||node.getAttribute("w:"+name)||node.getAttribute(name)}
function xml(str){return new DOMParser().parseFromString(str,"application/xml")}
function twipCm(v){return Number(v||0)/1440*2.54}
function ptFromHalf(v){return Number(v||0)/2}
function wordCount(s){return clean(s).split(/\s+/).filter(Boolean).length}
function paragraphsOf(s){return (s||"").split(/\n+/).map(clean).filter(Boolean)}
function hasAny(t,arr){const n=norm(t);return arr.some(x=>n.includes(norm(x)))}
function pct(n,d){return d?100*n/d:0}
function round1(n){return Math.round(n*10)/10}
function statusPill(ok,warn=false){return `<span class="pill ${ok?'ok':warn?'warn':'bad'}">${ok?'CUMPLE':warn?'PARCIAL':'NO CUMPLE'}</span>`}

async function sha256(buffer){const h=await crypto.subtle.digest('SHA-256',buffer);return [...new Uint8Array(h)].map(b=>b.toString(16).padStart(2,'0')).join('')}

function inheritStyle(styleId,styles,seen=new Set()){
  if(!styleId||!styles[styleId]||seen.has(styleId))return {};
  seen.add(styleId); const st=styles[styleId], base=inheritStyle(st.basedOn,styles,seen);
  return {...base,...st.props};
}

async function parseDocx(buffer){
  const zip=await JSZip.loadAsync(buffer);
  const get=async p=>zip.file(p)?await zip.file(p).async('string'):'';
  const [docStr,stylesStr,appStr]=await Promise.all([get('word/document.xml'),get('word/styles.xml'),get('docProps/app.xml')]);
  if(!docStr) throw new Error('El DOCX no contiene word/document.xml');
  const D=xml(docStr), S=stylesStr?xml(stylesStr):null, A=appStr?xml(appStr):null;
  const styles={};
  if(S){[...qn(S,'style')].forEach(st=>{const id=attr(st,'styleId');if(!id)return;const nameNode=qn(st,'name')[0],based=qn(st,'basedOn')[0],rPr=qn(st,'rPr')[0],pPr=qn(st,'pPr')[0];let props={};if(rPr){const rf=qn(rPr,'rFonts')[0],sz=qn(rPr,'sz')[0];props.font=rf&&(attr(rf,'ascii')||attr(rf,'hAnsi'));props.size=sz?ptFromHalf(attr(sz,'val')):null;props.bold=!!qn(rPr,'b')[0];props.italic=!!qn(rPr,'i')[0]}if(pPr){const sp=qn(pPr,'spacing')[0],jc=qn(pPr,'jc')[0];props.line=sp?Number(attr(sp,'line')||0):0;props.before=sp?Number(attr(sp,'before')||0):0;props.after=sp?Number(attr(sp,'after')||0):0;props.align=jc?attr(jc,'val'):null}styles[id]={name:nameNode?attr(nameNode,'val'):id,basedOn:based?attr(based,'val'):null,props}})}
  const paras=[];
  [...qn(D,'p')].forEach((p,idx)=>{
    const text=[...qn(p,'t')].map(x=>x.textContent).join(''); if(!text.trim())return;
    const pPr=qn(p,'pPr')[0], stNode=pPr&&qn(pPr,'pStyle')[0], styleId=stNode?attr(stNode,'val'):'';
    const inherited=inheritStyle(styleId,styles); const sp=pPr&&qn(pPr,'spacing')[0], jc=pPr&&qn(pPr,'jc')[0];
    let runFonts=[],sizes=[],boldCount=0,runCount=0,italCount=0;
    [...qn(p,'r')].forEach(r=>{const tx=[...qn(r,'t')].map(x=>x.textContent).join('');if(!tx.trim())return;runCount++;const rp=qn(r,'rPr')[0];if(rp){const rf=qn(rp,'rFonts')[0],sz=qn(rp,'sz')[0];if(rf)runFonts.push(attr(rf,'ascii')||attr(rf,'hAnsi'));if(sz)sizes.push(ptFromHalf(attr(sz,'val')));if(qn(rp,'b')[0])boldCount++;if(qn(rp,'i')[0])italCount++;}});
    const numPr=pPr&&qn(pPr,'numPr')[0];
    paras.push({idx,text:clean(text),styleId,styleName:(styles[styleId]?.name||''),font:runFonts.find(Boolean)||inherited.font||'',size:sizes.find(x=>x)||inherited.size||null,bold:runCount?boldCount/runCount>.5:!!inherited.bold,italic:runCount?italCount/runCount>.5:!!inherited.italic,align:(jc?attr(jc,'val'):null)||inherited.align||'',line:sp?Number(attr(sp,'line')||0):inherited.line||0,before:sp?Number(attr(sp,'before')||0):inherited.before||0,after:sp?Number(attr(sp,'after')||0):inherited.after||0,numbered:!!numPr});
  });
  const sects=[...qn(D,'sectPr')].map(sec=>{const pg=qn(sec,'pgSz')[0],mar=qn(sec,'pgMar')[0],num=qn(sec,'pgNumType')[0];return {w:pg?Number(attr(pg,'w')):0,h:pg?Number(attr(pg,'h')):0,left:mar?Number(attr(mar,'left')):0,right:mar?Number(attr(mar,'right')):0,top:mar?Number(attr(mar,'top')):0,bottom:mar?Number(attr(mar,'bottom')):0,pageFmt:num?attr(num,'fmt'):null,pageStart:num?attr(num,'start'):null,titlePg:!!qn(sec,'titlePg')[0]}});
  const footers=[];for(const f of Object.keys(zip.files).filter(x=>/^word\/footer\d+\.xml$/.test(x))){const F=xml(await get(f));footers.push({file:f,text:[...qn(F,'t')].map(x=>x.textContent).join(' '),center:[...qn(F,'jc')].some(x=>attr(x,'val')==='center'),pageField:(await get(f)).includes('PAGE')})}
  let pages=null;if(A){const pn=A.getElementsByTagName('Pages')[0];if(pn)pages=Number(pn.textContent)||null}
  const media=Object.keys(zip.files).filter(x=>/^word\/media\//.test(x)).length;
  const tables=[...qn(D,'tbl')].map((t,ti)=>{
    const pr=qn(t,'tblPr')[0],b=pr&&qn(pr,'tblBorders')[0],ih=b&&qn(b,'insideH')[0];
    const rows=[...qn(t,'tr')].map(tr=>[...qn(tr,'tc')].map(tc=>{
      const text=clean([...qn(tc,'t')].map(x=>x.textContent).join(' '));
      const ps=[...qn(tc,'p')];
      const aligns=[],sizes=[];
      ps.forEach(p=>{const pp=qn(p,'pPr')[0],jc=pp&&qn(pp,'jc')[0];if(jc)aligns.push(attr(jc,'val'));[...qn(p,'r')].forEach(r=>{const rp=qn(r,'rPr')[0],sz=rp&&qn(rp,'sz')[0];if(sz)sizes.push(ptFromHalf(attr(sz,'val')));});});
      return {text,align:aligns.find(Boolean)||'',size:sizes.find(x=>x)||null};
    }));
    return {index:ti,insideH:ih?attr(ih,'val'):null,text:clean([...qn(t,'t')].map(x=>x.textContent).join(' ')),rows};
  });
  return {paras,text:paras.map(p=>p.text).join('\n'),styles,sects,footers,pages,media,tables};
}

function extractCover(doc){
 const first=doc.paras.slice(0,35).map(p=>p.text);
 let name=''; for(let i=0;i<first.length;i++){let m=first[i].match(/Postulante\s*:\s*(.+)/i);if(m){name=clean(m[1]);break}}
 let title=''; const pgIndex=first.findIndex(x=>/PROYECTO DE GRADO/i.test(x)); if(pgIndex>=0){for(let i=pgIndex+1;i<Math.min(first.length,pgIndex+8);i++){if(/Postulante|Tutor|El Alto|Bolivia|20\d{2}/i.test(first[i]))break;title+=(title?' ':'')+first[i].replace(/[“”"]/g,'')}}
 return {name,title:clean(title)};
}
function findTocPages(text){
 const lines=(text||'').split(/\n/).map(clean).filter(Boolean),out={};
 const specs=[['p1',/CAP[IÍ]TULO\s+(?:I|1)\.?\s+GENERALIDADES/i],['p2',/CAP[IÍ]TULO\s+(?:II|2)\.?\s+MARCO\s+TE[ÓO]RICO/i],['p3',/CAP[IÍ]TULO\s+(?:III|3)\.?\s+INGENIER[IÍ]A/i],['p4',/CAP[IÍ]TULO\s+(?:IV|4)\.?\s+PRUEBAS/i],['p5',/CAP[IÍ]TULO\s+(?:V|5)\.?\s+(AN[AÁ]LISIS|FUNDAMENT)/i],['p6',/CAP[IÍ]TULO\s+(?:VI|6)\.?\s+CONCLUSIONES/i],['pbib',/^(BIBLIOGRAF[IÍ]A|REFERENCIAS\s+BIBLIOGR[AÁ]FICAS)/i]];
 for(const [k,re] of specs){for(const line of lines.slice(0,650)){if(re.test(line)){const nums=line.match(/\b\d{1,3}\b/g);if(nums?.length){out[k]=Number(nums.at(-1));break}}}}
 return out;
}
function sectionText(text,startRe,endRe){const lines=text.split(/\n/);let s=-1,e=lines.length;for(let i=0;i<lines.length;i++){if(s<0&&startRe.test(lines[i])){s=i;continue}if(s>=0&&endRe&&endRe.test(lines[i])){e=i;break}}return s>=0?lines.slice(s,e).join('\n'):''}
function buildSections(text){
 const lines=(text||'').split(/\n/).map(clean);
 const roman={1:'I',2:'II',3:'III',4:'IV',5:'V',6:'VI'};
 const reFor=n=>new RegExp('^CAP[IÍ]TULO\\s+(?:'+roman[n]+'|'+n+')\\.?\\b','i');
 const lastIndex=re=>{let hit=-1;for(let i=0;i<lines.length;i++)if(re.test(lines[i]))hit=i;return hit};
 const st={};for(let n=1;n<=6;n++)st[n]=lastIndex(reFor(n));
 let refs=-1;for(let i=Math.max(0,st[6]);i<lines.length;i++)if(/^(BIBLIOGRAF[IÍ]A|REFERENCIAS\s+BIBLIOGR[AÁ]FICAS)\b/i.test(lines[i])){refs=i;break}
 let gloss=-1;if(refs>=0){for(let i=refs+1;i<lines.length;i++)if(/^GLOSARIO\b/i.test(lines[i])){gloss=i;break}}
 const cut=(a,b)=>a>=0?lines.slice(a,b>=0?b:lines.length).join('\n'):'';
 let sum=-1;if(st[1]>=0){for(let i=st[1]-1;i>=0;i--)if(/^RESUMEN\s*$/i.test(lines[i])){sum=i;break}}
 return {c1:cut(st[1],st[2]),c2:cut(st[2],st[3]),c3:cut(st[3],st[4]),c4:cut(st[4],st[5]),c5:cut(st[5],st[6]),c6:cut(st[6],refs),refs:cut(refs,gloss),summary:cut(sum,st[1])};
}
function objectiveTexts(c1){const lines=c1.split(/\n/).map(clean);let general='',spec=[];for(let i=0;i<lines.length;i++){if(/OBJETIVO GENERAL/i.test(lines[i])){for(let j=i+1;j<Math.min(lines.length,i+6);j++){if(lines[j]&&!/OBJETIVOS ESPEC/i.test(lines[j])){general=lines[j];break}}}if(/OBJETIVOS ESPEC[IÍ]FICOS/i.test(lines[i])){for(let j=i+1;j<lines.length;j++){if(/^1\.(7|8|9)\b/.test(lines[j])||/JUSTIFICACI[ÓO]N|ALCANCES|METODOLOG[IÍ]A/i.test(lines[j]))break;if(lines[j].length>18)spec.push(lines[j].replace(/^[•\-–\d.)\s]+/,''))}}}return{general,spec:spec.slice(0,12)}}
function firstPersonHits(t){const matches=[];const n=(t||'');const pron=n.match(/\b(yo|nosotros|nosotras|nuestro|nuestra|nuestros|nuestras|me\s+(?:permiti[oó]|permiti)|mi\s+proyecto)\b/gi)||[];matches.push(...pron);const verbs=n.match(/\b[a-záéíóúñü]{3,}(?:amos|emos|imos)\b/gi)||[];const exceptions=new Set(['sistemas','problemas','programas','diagramas','esquemas','teoremas','idiomas']);matches.push(...verbs.filter(v=>!exceptions.has(norm(v))));return [...new Set(matches)].slice(0,60)}
function citationStats(text,refs){const par=[...(text.matchAll(/\(([A-ZÁÉÍÓÚÑ][A-Za-zÁÉÍÓÚÑáéíóúñ.&\s-]{1,80}),\s*(20\d{2}|19\d{2})[^)]*\)/g))];const nar=[...(text.matchAll(/\b([A-ZÁÉÍÓÚÑ][A-Za-zÁÉÍÓÚÑáéíóúñ-]+)\s*\((20\d{2}|19\d{2})\)/g))];const citations=[...par,...nar].map(m=>({author:clean(m[1]).split(/\s|&/)[0].replace(/[,.;]/g,''),year:m[2]}));const refLines=(refs||'').split(/\n/).map(clean).filter(x=>/\(?(19|20)\d{2}[a-z]?\)?/.test(x)&&x.length>20);let missing=0;for(const c of citations){if(!refLines.some(r=>norm(r).includes(norm(c.author))&&r.includes(c.year)))missing++}const pagBad=(text.match(/\b(p[aá]g\.|p[aá]gs\.)\s*\d+/gi)||[]).length;return{citations,refLines,missing,pagBad}}
function headingSamples(doc){return doc.paras.filter(p=>/^(CAP[IÍ]TULO\s+(?:[IVX]+|[1-6])\b|\d+(?:\.\d+){1,4}\.?\s+)/i.test(p.text)).slice(0,100)}
function headingCompliance(doc){const hs=headingSamples(doc);let checks={chapter:[],l2:[],l3:[],deep:[]};for(const p of hs){let m=p.text.match(/^(\d+(?:\.\d+)+)/);if(/^CAP[IÍ]TULO\s+(?:[IVX]+|[1-6])/i.test(p.text))checks.chapter.push(p);else if(m){const depth=(m[1].match(/\./g)||[]).length+1;if(depth===2)checks.l2.push(p);else if(depth===3)checks.l3.push(p);else checks.deep.push(p)}}
 const evalGroup=(a,size,upper)=>{if(!a.length)return null;let ok=0;for(const p of a){const font=!p.font||/Times New Roman/i.test(p.font),sz=!p.size||Math.abs(p.size-size)<=.6,bold=p.bold||/heading|t[ií]tulo/i.test(p.styleName),body=p.text.replace(/^CAP[IÍ]TULO\s+(?:[IVX]+|[1-6])\.?\s*|^\d+(?:\.\d+)+\.?\s*/i,'').trim(),caseOk=upper?(body===body.toUpperCase()):(body!==body.toUpperCase()||body.length<5);if(font&&sz&&bold&&caseOk)ok++}return ok/a.length};
 return {groups:checks,chapter:evalGroup(checks.chapter,16,true),l2:evalGroup(checks.l2,14,true),l3:evalGroup(checks.l3,12,true),deep:evalGroup(checks.deep,12,false)} }
function formatAnalysis(doc){const sec=doc.sects.at(-1)||{};const letter=(Math.abs(twipCm(sec.w)-21.59)<.5&&Math.abs(twipCm(sec.h)-27.94)<.7)||(Math.abs(twipCm(sec.h)-21.59)<.5&&Math.abs(twipCm(sec.w)-27.94)<.7);const margins={left:twipCm(sec.left),right:twipCm(sec.right),top:twipCm(sec.top),bottom:twipCm(sec.bottom)};const marginsOk=Math.abs(margins.left-3.5)<.25&&Math.abs(margins.right-2.5)<.25&&Math.abs(margins.top-2.5)<.25&&Math.abs(margins.bottom-2.5)<.25;const body=doc.paras.filter(p=>p.text.length>80&&!/CAP[IÍ]TULO|^\d+(\.\d+)+/.test(p.text));const fontRatio=body.length?body.filter(p=>(!p.font||/Times New Roman/i.test(p.font))&&(!p.size||Math.abs(p.size-12)<.6)).length/body.length:0;const lineRatio=body.length?body.filter(p=>!p.line||Math.abs(p.line-360)<45).length/body.length:0;const footOk=doc.footers.some(f=>f.center&&f.pageField);return{letter,margins,marginsOk,fontRatio,lineRatio,footOk,headings:headingCompliance(doc)}}
function pageRatioFromInputs(){const v=id=>Number($(id).value);const p1=v('p1'),p2=v('p2'),p3=v('p3'),pb=v('pbib');if([p1,p2,p3,pb].some(x=>!Number.isFinite(x)||x<=0)||p3<=p2||pb<=p1)return null;const mt=p3-p2,total=pb-p1,ratio=mt/total*100;STATE.pageRatio={mt,total,ratio};return STATE.pageRatio}
function showPageRatio(){const r=pageRatioFromInputs();if(!r){$('pageResult').className='output-box warn';$('pageResult').innerHTML='Completa al menos Cap. I, Cap. II, Cap. III y Bibliografía con números válidos.';$('pageResult').classList.remove('hidden');return}const ok=r.ratio<=25;$('pageResult').className='output-box '+(ok?'ok':'bad');$('pageResult').innerHTML=`<b>${ok?'🟢 CUMPLE':'🔴 EXCEDE EL LÍMITE'}</b><p>Marco Teórico: ${r.mt} páginas de ${r.total} páginas entre Capítulo I y final del Capítulo VI = <b>${r.ratio.toFixed(2)} %</b>.</p>${ok?'<p>Se encuentra dentro del máximo de 25 %.</p>':'<p>Debe reducirse el Marco Teórico o trasladar material excesivamente descriptivo a anexos/apéndices cuando corresponda. Conservar solo teoría necesaria para comprender y sustentar el diseño.</p>'}`;$('pageResult').classList.remove('hidden')}

function addRubric(name,max,score,detail){STATE.rubric.push({name,max,score:round1(clamp(score,0,max)),detail})}
function issue(severity,title,why,how,example=''){STATE.issues.push({severity,title,why,how,example})}
function sectionPresence(s){return clean(s).length>120}
function citationCount(t){return ((t||'').match(/\([^)]*(?:19|20)\d{2}[^)]*\)/g)||[]).length+((t||'').match(/\b[A-ZÁÉÍÓÚÑ][A-Za-zÁÉÍÓÚÑáéíóúñ-]+\s*\((?:19|20)\d{2}\)/g)||[]).length}
function critical(title,why,how,example=''){issue('critical',title,why,how,example);if(!STATE.locks.includes(title))STATE.locks.push(title)}
function quantifiedSignals(t){return ((t||'').match(/\b\d+(?:[.,]\d+)?\s*(?:%|Bs\.?|V|mV|A|mA|W|kW|kWh|Hz|kHz|MHz|GHz|ms|s|min|h|ppm|°C|lux|m|cm|mm|km|Mbps|dB|kg|g|L|mL)\b/gi)||[]).length}
function sourceSignals(t){return citationCount(t)+((t||'').match(/\bFuente\s*:/gi)||[]).length+((t||'').match(/\b(?:según|de acuerdo con)\b/gi)||[]).length}
function blockByHeading(text,titleRe){const lines=(text||'').split(/\n/).map(clean);let s=-1,depth=2,prefix='';for(let i=0;i<lines.length;i++){if(titleRe.test(lines[i])){s=i;const m=lines[i].match(/^(\d+(?:\.\d+)+)/);if(m){prefix=m[1];depth=prefix.split('.').length}break}}if(s<0)return'';let e=lines.length;for(let i=s+1;i<lines.length;i++){const m=lines[i].match(/^(\d+(?:\.\d+)+)\b/);if(m){const d=m[1].split('.').length;if(d<=depth&&m[1]!==prefix){e=i;break}}}return lines.slice(s,e).join('\n')}
function numberedBlocks(text,chapter,depth=2){const lines=(text||'').split(/\n/).map(clean);const hs=[];const re=new RegExp('^'+chapter.replace('.','\\.')+'(?:\\.\\d+){'+(depth-1)+'}\\b');for(let i=0;i<lines.length;i++){const m=lines[i].match(/^(\d+(?:\.\d+)+)\b/);if(m&&m[1].split('.').length===depth&&m[1].startsWith(chapter+'.'))hs.push({i,heading:lines[i],num:m[1]})}return hs.map((h,k)=>({heading:h.heading,num:h.num,text:lines.slice(h.i,(hs[k+1]?.i??lines.length)).join('\n')}))}
function conciseAudit(block,labels){const subs=[];for(const label of labels){const b=blockByHeading(block,new RegExp(label,'i'));if(b)subs.push({label,text:b,words:wordCount(b),paras:paragraphsOf(b).filter(x=>!/^\d+(?:\.\d+)+/.test(x)).length})}return subs}
function posAny(t,keys){const n=norm(t);let p=-1;for(const k of keys){const q=n.indexOf(norm(k));if(q>=0&&(p<0||q<p))p=q}return p}
function meaningfulTokens(s){const stop=new Set('desarrollar disenar diseñar implementar realizar evaluar determinar proponer optimizar crear construir modelar sistema prototipo proyecto para del de la las los un una en con por y e que se al como sobre mediante'.split(' '));return [...new Set(norm(s).replace(/[^a-z0-9áéíóúñ]+/g,' ').split(/\s+/).filter(x=>x.length>4&&!stop.has(x)))]}
function objectiveTarget(o){const n=norm(o);if(/econom|costo|presupuesto|financier/.test(n))return'c5';if(/prueb|valid|verific|evaluar.*funcion|desempen|medicion|medir.*resultado/.test(n))return'c4';if(/problemat|diagnost|estudio|investig/.test(n))return'other';return'c3'}
function objectiveCoverage(objectives,chapterText,target){const list=objectives.filter(o=>objectiveTarget(o)===target);if(!list.length)return{list,hit:0,ratio:1,missing:[]};const n=norm(chapterText),missing=[];let hit=0;for(const o of list){const toks=meaningfulTokens(o);const matches=toks.filter(x=>n.includes(x)).length;const ok=matches>=Math.min(2,Math.max(1,Math.ceil(toks.length*.25)));if(ok)hit++;else missing.push(o)}return{list,hit,ratio:hit/list.length,missing}}
function costTableAudit(doc){const costTables=(doc.tables||[]).filter(t=>/(costo|costos|monto|precio|bs\.?)/i.test(t.text));let knownMoney=0,rightMoney=0,centerMoney=0,badFont=0;const seen=new Map();for(const t of costTables){if(!t.rows?.length)continue;let headerRows=t.rows.slice(0,2);let maxCols=Math.max(...t.rows.map(r=>r.length),0);const moneyCols=[];for(let c=0;c<maxCols;c++){const h=headerRows.map(r=>r[c]?.text||'').join(' ');if(/costo|monto|precio|bs\.?/i.test(h)&&!/cantidad/i.test(h))moneyCols.push(c)}for(let r=1;r<t.rows.length;r++){const row=t.rows[r];const desc=clean(row[0]?.text||'');if(desc&&desc.length>5&&!/^(total|fuente|nota)/i.test(desc)){const key=norm(desc).replace(/\([^)]*\)/g,'').replace(/\b\d+(?:[.,]\d+)?\b/g,'').replace(/[^a-záéíóúñ]+/g,' ').trim();if(key.length>7){if(!seen.has(key))seen.set(key,new Set());seen.get(key).add(t.index)}}for(const c of moneyCols){const cell=row[c];if(!cell||!/[0-9]/.test(cell.text))continue;if(cell.align){knownMoney++;if(cell.align==='right'||cell.align==='end')rightMoney++;if(cell.align==='center')centerMoney++}if(cell.size&&Math.abs(cell.size-10)>.6)badFont++;}}}const duplicates=[...seen.entries()].filter(([k,v])=>v.size>1).map(([k])=>k).slice(0,12);return{count:costTables.length,knownMoney,rightMoney,centerMoney,badFont,duplicates}}
function c2CitationAudit(t){const blocks=numberedBlocks(t,'2',2).filter(b=>wordCount(b.text)>110);const uncited=blocks.filter(b=>citationCount(b.text)===0);return{blocks,uncited,ratio:blocks.length?uncited.length/blocks.length:1}}
function chapter4TestCount(t){return ((t||'').match(/^4\.\d+(?:\.\d+)+[^\n]*(?:PRUEB|VERIFIC|CALIBR|VALID|ENSAY|EVALUACI[ÓO]N|DESEMPEÑ|RESPUESTA)/gmi)||[]).length}
